"""Builds the included implementation report; not required to run the app."""
from reportlab.lib import colors
from reportlab.lib.pagesizes import A4
from reportlab.lib.styles import ParagraphStyle, getSampleStyleSheet
from reportlab.lib.units import mm
from reportlab.platypus import (
    Image,
    PageBreak,
    Paragraph,
    SimpleDocTemplate,
    Spacer,
    Table,
    TableStyle,
)

OUT = "Dr_Nilesh_Shah_Stocks_FairScope_Application_Report.pdf"
navy=colors.HexColor("#10233F"); blue=colors.HexColor("#2563EB"); light=colors.HexColor("#EEF3F8")
styles=getSampleStyleSheet()
styles.add(ParagraphStyle(name="PX",parent=styles["BodyText"],fontSize=9.5,leading=14,spaceAfter=6))
styles.add(ParagraphStyle(name="HX",parent=styles["Heading2"],fontSize=15,leading=19,textColor=navy,spaceBefore=10,spaceAfter=7))
styles.add(ParagraphStyle(name="TX",parent=styles["Title"],fontSize=19,leading=24,textColor=navy,spaceAfter=7))

def footer(canvas,doc):
    canvas.saveState(); canvas.setStrokeColor(colors.HexColor("#D7DEE8")); canvas.line(18*mm,16*mm,192*mm,16*mm)
    canvas.setFont("Helvetica",7.5); canvas.setFillColor(colors.HexColor("#68778A")); canvas.drawString(18*mm,10*mm,"DR. NILESH SHAH - STOCKS FAIRSCOPE • Application report • 20 August 2026"); canvas.drawRightString(192*mm,10*mm,f"Page {doc.page}"); canvas.restoreState()

doc=SimpleDocTemplate(OUT,pagesize=A4,leftMargin=18*mm,rightMargin=18*mm,topMargin=17*mm,bottomMargin=20*mm,title="DR. NILESH SHAH - STOCKS FAIRSCOPE Application Report")
logo=Image("assets/logo_256.png",width=28*mm,height=28*mm)
brand=[Paragraph("DR. NILESH SHAH - STOCKS FAIRSCOPE",styles["TX"]),Paragraph("US & Indian Stock Fair Value Desktop Application",ParagraphStyle(name="SubX",parent=styles["Normal"],fontSize=12,textColor=blue,spaceAfter=6)),Paragraph("Project report • Version 10.1 • 20 August 2026",styles["PX"])]
cover=Table([[logo,brand]],colWidths=[34*mm,138*mm],rowHeights=[32*mm]); cover.setStyle(TableStyle([("VALIGN",(0,0),(-1,-1),"MIDDLE"),("LEFTPADDING",(0,0),(-1,-1),0),("RIGHTPADDING",(0,0),(-1,-1),0),("TOPPADDING",(0,0),(-1,-1),0),("BOTTOMPADDING",(0,0),(-1,-1),0)]))
story=[cover,Spacer(1,6*mm)]
summary=[["Selected requirement","Implemented solution"],["Markets","US equities, NSE, and BSE"],["Fair-value strategy","Sector-aware blend of two-stage DCF/residual income, Graham/book, and live peers"],["Assumption mode","Automatic base assumptions plus conservative/base/optimistic scenarios"],["Data source","Yahoo primary plus Screener.in and NSE/BSE website verification; no API key"],["Currency & uncertainty","Native currency; dynamic 15–50% risk/data-aware valuation buffer"],["Delivery","Modern Qt app plus Windows x64 signing-ready Inno Setup pipeline"],["Reports","Full per-stock PDF export; included live AAPL sample"],["Batch analysis","Import up to 100 CSV/TXT/Excel symbols; export CSV and branded PDF summary"],["Search","Debounced company/ticker autocomplete for US, NSE and BSE"],["Visual analysis","Native Qt and PDF charts for price, models, trends, sensitivity and Monte Carlo"],["Assumption review","Automatic-vs-reviewed table, presets, locks, validation, notes and PDF disclosure"],["Data lineage","Metric-level source URLs, periods, transformations, statuses, CSV and PDF citations"],["Model audit","Unique IDs, parent chain, versions, events, seed, JSON export and SHA-256 verification"],["Financial companies","Specialized bank/NBFC/insurer data, valuation, risk, lineage, audit and PDF review"],["Coverage fallback","Revenue, book/net-cash and peer P/B heuristics for loss-making/negative-FCF equities"],["External review","User-cited Moneycontrol/filing values with lineage, child audit ID and no automated scraping"],["Watchlists","Local SQLite watchlist with state-aware valuation-buffer, price, upside, risk, discrepancy and FV-change alerts"],["Corporate monitor","SEC/NSE/BSE/Screener filings, announcements, dividends, splits and persistent read history"],["Local database","WAL SQLite stock cache, stale fallback, settings, and 1,000-record valuation audit history"],["Background jobs","Bounded parallelism, retry/backoff, determinate progress, pause/cancel, partial persistence and recovery"],["Testing","Cross-platform Python 3.11–3.13 CI, coverage, PDF/import/extreme/cache/100-stock/network regression suites"],["Diagnostics","Sanitized rotating logs, provider/database health, maintenance, support ZIP and colourful watchlist PDF"],["Privacy","OS-keychain/Fernet secrets, restrictive permissions, masked watchlist UI, redacted support exports"],["PDF design","Branded cover, executive summary, contents, bookmarks, score bars, charts, audit and lineage appendices"],["Uncertainty language","Valuation-buffer terminology, no Buy/Sell labels, and explicit no-guarantee/loss-protection warnings"],["Phase 2","Sensitivity matrix, reverse DCF, business quality, governance screen, numeric confidence"],["Simulation","2,000-run deterministic Monte Carlo valuation with percentile ranges"]]
t=Table(summary,colWidths=[48*mm,124*mm],repeatRows=1)
t.setStyle(TableStyle([("BACKGROUND",(0,0),(-1,0),navy),("TEXTCOLOR",(0,0),(-1,0),colors.white),("FONT",(0,0),(-1,0),"Helvetica-Bold",8.5),("FONT",(0,1),(-1,-1),"Helvetica",8.5),("ROWBACKGROUNDS",(0,1),(-1,-1),[colors.white,light]),("GRID",(0,0),(-1,-1),.35,colors.HexColor("#CBD5E1")),("VALIGN",(0,0),(-1,-1),"TOP"),("TOPPADDING",(0,0),(-1,-1),6),("BOTTOMPADDING",(0,0),(-1,-1),6)])); story.append(t)
story += [Paragraph("Product overview",styles["HX"]),Paragraph("DR. NILESH SHAH - STOCKS FAIRSCOPE is a responsive desktop research tool designed to turn a ticker into a transparent scenario valuation. The modern Qt interface includes visual analysis, lineage/audit review, and specialized bank, NBFC, lender, and insurer workflows. Yahoo Finance requests and batch work use Qt thread-pool workers so the window remains responsive.",styles["PX"]),Paragraph("Primary workflow",styles["HX"])]
for x in ["Choose US, NSE, or BSE and enter a ticker.","Retrieve latest price, profile, market metrics, cash flow, EPS, book value, and growth indicators.","Apply market-aware guardrails and calculate three scenarios.","Review model-level and blended values, upside/downside, and valuation-buffer threshold.","Optionally edit assumptions and regenerate the analysis, then export a full PDF."]:
    story.append(Paragraph("• "+x,styles["PX"]))
story += [PageBreak(),Paragraph("Phase-1 valuation design",styles["TX"]),Paragraph("Normalized fundamentals",styles["HX"]),Paragraph("Up to five annual free-cash-flow, revenue, and net-income observations are collected. Median normalization reduces one-year distortions, while historical and reported growth are combined under sector-specific caps.",styles["PX"]),Paragraph("Two-stage intrinsic value",styles["HX"]),Paragraph("Operating companies use a ten-year normalized FCF-per-share DCF: initial growth applies for five years and then fades toward terminal growth. Financial institutions use residual income instead.",styles["PX"]),Paragraph("Live peer comparison",styles["HX"]),Paragraph("Real peers use Yahoo screening. Indian prices and selected ratios are cross-checked against Screener.in and NSE/BSE website endpoints with discrepancy warnings. Median P/E is used for most companies; financial and real-estate profiles use median P/B.",styles["PX"]),Paragraph("Sector and uncertainty profiles",styles["HX"]),Paragraph("Financial, real-estate, cyclical, utility, technology, and standard-company profiles use different weights and limits. The required valuation buffer increases for leverage, weak coverage, FCF instability, incomplete data, cyclicality, and model disagreement; it does not guarantee loss protection.",styles["PX"]),Paragraph("Phase-2 analytics",styles["HX"]),Paragraph("A 5×5 valuation sensitivity matrix, reverse DCF implied growth, business-quality score, governance-risk screen, and expanded numeric confidence score are shown in the app and reports.",styles["PX"]),Paragraph("Monte Carlo uncertainty analysis",styles["HX"]),Paragraph("Every stock receives a 2,000-run reproducible Monte Carlo valuation distribution with percentile ranges. These are model outputs, not return forecasts.",styles["PX"]),Paragraph("Scenario rules",styles["HX"])]
sc=[["Scenario","Growth","Discount rate","Terminal growth"],["Conservative","Base − 4 percentage points","Base + 2 points","Base − 1 point"],["Base","Bounded data estimate","10% US / 12% India","3% US / 5.5% India"],["Optimistic","Base + 4 points","Base − 1.5 points","Base + 1.5 points (guarded)"]]
st=Table(sc,colWidths=[31*mm,55*mm,43*mm,43*mm],repeatRows=1); st.setStyle(TableStyle([("BACKGROUND",(0,0),(-1,0),navy),("TEXTCOLOR",(0,0),(-1,0),colors.white),("FONT",(0,0),(-1,0),"Helvetica-Bold",8),("FONT",(0,1),(-1,-1),"Helvetica",8),("ROWBACKGROUNDS",(0,1),(-1,-1),[colors.white,light]),("GRID",(0,0),(-1,-1),.35,colors.HexColor("#CBD5E1")),("VALIGN",(0,0),(-1,-1),"TOP"),("TOPPADDING",(0,0),(-1,-1),5),("BOTTOMPADDING",(0,0),(-1,-1),5)])); story.append(st)
story += [Paragraph("Resilience",styles["HX"]),Paragraph("When a model lacks required positive inputs, it is excluded and remaining weights are re-normalized. The app reports model coverage and data warnings rather than silently replacing missing fundamentals. Input guardrails require discount rate above terminal growth, a 1–20 year forecast horizon, and valid non-negative weights.",styles["PX"]),PageBreak(),Paragraph("Delivery, testing & limitations",styles["TX"]),Paragraph("Included files",styles["HX"]),Paragraph("The downloadable ZIP contains source, Windows x64 build/sign/verify scripts, dependency list, Windows and Unix launchers, single-stock and batch PDF exporters, CSV/TXT/Excel import support, offline unit tests, setup guide, this report, and a sample AAPL valuation PDF generated from the live feed.",styles["PX"]),Paragraph("Verification completed",styles["HX"])]
for x in ["Offline tests cover scenarios, dynamic valuation buffer, peers, sector selection, reverse DCF, sensitivity, quality/governance, Monte Carlo, batch import, and missing-model reweighting.","All Python modules passed byte-code compilation.","Yahoo lookups were verified for US/NSE/BSE; Screener.in and BSE website checks were validated, while NSE access remains location-dependent.","The full PDF report generator was executed successfully for AAPL."]:
    story.append(Paragraph("• "+x,styles["PX"]))
story += [Paragraph("Known limitations",styles["HX"])]
for x in ["Free Yahoo/Screener/NSE/BSE website data can be delayed, unavailable, incomplete, rate-limited, blocked, or changed without notice.","A bounded P/E normalization is not the same as a researched peer-set median.","Banks, insurers, REITs, cyclicals, loss-making firms, and unusual capital structures often need specialized valuation methods.","Intrinsic value is assumption-sensitive and is not a forecast or guarantee.","An executable must be built on the target operating system; source launchers are supplied for portability."]:
    story.append(Paragraph("• "+x,styles["PX"]))
story += [Paragraph("Disclaimer",styles["HX"]),Paragraph("DR. NILESH SHAH - STOCKS FAIRSCOPE is for education and research only. It does not provide investment advice, recommendations, offers, or assurances of return. Users should verify data against official filings and consult a SEBI-registered investment adviser in India or an appropriately registered professional in their jurisdiction.",styles["PX"])]
